package io.rift.cronos;
import org.json.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Optional public read-only index coordinator probe. Repository is RAM, NOT actual Android SQLite.
 * Args public contract, public owner. One recent 3-block start plus one 3-block overlapped resume.
 * No secret, write-RPC, signing, persistent account access or wallet creation. */
public final class NativeIndexProbe {
 public static void main(String[] args)throws Exception{if(args.length!=2)throw new IllegalArgumentException("Pass public contract and owner");String contract=ReadPolicy.address(args[0]),owner=ReadPolicy.address(args[1]),source=UUID.randomUUID().toString();try(RequestControl control=new RequestControl(60000)){
  TransferDiscovery.Rpc rpc=new TransferDiscovery.Rpc(){public void requireCronos()throws Exception{if(!"0x19".equals(call("eth_chainId",new JSONArray())))throw new IllegalStateException("Wrong chain");}public Object call(String method,JSONArray params)throws Exception{if(!Arrays.asList("eth_chainId","eth_blockNumber","eth_getBlockByNumber","eth_getLogs").contains(method))throw new IllegalArgumentException();byte[] request=new JSONObject().put("jsonrpc","2.0").put("id",1).put("method",method).put("params",params).toString().getBytes(StandardCharsets.UTF_8);PinnedHttps.Result response=PinnedHttps.post("https://evm.cronos.org","",request,control);if(response.status!=200)throw new IllegalStateException("Public provider HTTP "+response.status);JSONObject result=new JSONObject(JsonBudget.check(new String(response.body,StandardCharsets.UTF_8),262144,32));if(!"2.0".equals(result.optString("jsonrpc"))||result.optInt("id")!=1||result.has("error")||!result.has("result"))throw new IllegalStateException("Provider refused read");return result.get("result");}};
  DiscoveryIndex.Repository repo=new DiscoveryIndex.Repository(){long epoch;JSONObject state;public DiscoveryIndex.Snapshot load(String scope)throws Exception{return new DiscoveryIndex.Snapshot(epoch,state==null?null:new JSONObject(state.toString()));}public boolean commit(String scope,long expected,JSONObject value)throws Exception{if(epoch!=expected)return false;state=value==null?null:new JSONObject(value.toString());epoch++;return true;}};
  JSONObject first=DiscoveryIndex.advance(repo,rpc,owner,contract,"ERC-721",source,0,true,"recent","3",System.currentTimeMillis(),()->control.remaining(1000));JSONObject next=DiscoveryIndex.advance(repo,rpc,owner,contract,"ERC-721",source,Long.parseLong(first.getString("revision")),false,"recent","3",System.currentTimeMillis(),()->control.remaining(1000));if(!next.getBoolean("checkpointVerifiedNow")||!next.getString("revision").equals("2"))throw new IllegalStateException("Checkpoint not verified/advanced");System.out.println(new JSONObject().put("passed",true).put("chainId",25).put("scope","Real public RPC and index coordinator with RAM repository; NOT Android SQLite, positive holdings, finality or completeness acceptance").put("firstEnd",first.getString("endBlock")).put("resumedEnd",next.getString("endBlock")).put("revision",next.getString("revision")).put("candidateCount",next.getInt("candidateCount")).toString(2));
 }}
}
